INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-JR-A01', 'Frontend', 'Junior', 'Анализ', 'Анализ A01', 'Почему фильтр ниже может давать неожиданный результат? Исправьте его так, чтобы поиск не зависел от регистра и совпадение искалось в названии.', NULL, 'const visible = items.filter(item => item.name.includes(query));', '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-JR-A02', 'Frontend', 'Junior', 'Анализ', 'Анализ A02', 'Список строится вставкой данных API в innerHTML: list.innerHTML = `<li>${item.name}</li>`. Какой риск возникает, если имя содержит HTML-разметку, и как вывести значение как текст?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-JR-P01', 'Frontend', 'Junior', 'Практика', 'Практика P01', 'Реализуйте поиск по списку сотрудников. При вводе текста список должен показывать элементы, в имени или роли которых есть запрос без учёта регистра. Пустой запрос показывает весь список. Выводите поля безопасно как текст. Предусмотрите сообщение при отсутствии совпадений. Используйте предоставленную HTML-структуру и данные.', 'HTML/CSS/JavaScript', '<!doctype html>
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-MD-T01', 'Frontend', 'Middle', 'Теория', 'Теория T01', 'Почему состояние React следует обновлять иммутабельно, а не изменять вложенный объект на месте?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-MD-T02', 'Frontend', 'Middle', 'Теория', 'Теория T02', 'Для чего useEffect принимает массив зависимостей и как выбрать зависимости эффекта?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
