INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-MD-T05', 'Frontend', 'Middle', 'Теория', 'Теория T05', 'Назовите базовые требования доступности для поля поиска с кнопкой отправки.', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-MD-A01', 'Frontend', 'Middle', 'Анализ', 'Анализ A01', 'Найдите проблему с зависимостями эффекта и объясните, почему requests могут повторяться либо использовать устаревший query. Предложите исправление.', NULL, 'useEffect(() => { fetch(`/api/search?q=${query}`).then(r => r.json()).then(setItems); }, []);', '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-MD-A02', 'Frontend', 'Middle', 'Анализ', 'Анализ A02', 'Компонент отображает элементы с key={index}. После удаления первого элемента текст в поле ввода, находившемся внутри строки, оказывается у другого элемента. Почему и как исправить?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-MD-P01', 'Frontend', 'Middle', 'Практика', 'Практика P01', 'Реализуйте типизированный компонент поиска сотрудников, выполняющий запрос к /api/users?q=... при вводе от двух символов. Ответ API имеет формат User[]. Отображайте состояния загрузки, ошибки и пустого результата. Отменяйте предыдущий запрос при изменении поисковой строки и при размонтировании компонента, чтобы устаревший ответ не заменял актуальный. Обеспечьте метку для поля и доступное объявление статуса. API-клиент можно считать доступным через fetch.', 'TypeScript и React', 'import { useEffect, useState } from "react";
