INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-SR-A01', 'Frontend', 'Senior', 'Анализ', 'Анализ A01', 'Определите причины потенциального hydration mismatch и предложите минимальный принцип исправления.', NULL, 'function Clock() { return <span>{new Date().toLocaleTimeString()}</span>; }', '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-SR-A02', 'Frontend', 'Senior', 'Анализ', 'Анализ A02', 'Каталог содержит десятки тысяч строк. При каждом вводе фильтруются все записи и синхронно создаются DOM-узлы для всех совпадений. Как исследовать проблему и какие улучшения рассмотреть, не утверждая заранее, что они обязательно нужны?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('FE-SR-P01', 'Frontend', 'Senior', 'Практика', 'Практика P01', 'Реализуйте React-компонент автодополнения по endpoint /api/suggestions?q=... с ответом { items: Suggestion[] }, где Suggestion содержит id и label. Компонент должен иметь связанное с меткой поле ввода, открывающийся список вариантов, клавиатурное управление ArrowDown, ArrowUp, Enter и Escape, корректные роли combobox/listbox/option и объявление статуса. Не отправляйте запрос для пустого запроса; отменяйте устаревшие запросы при новом вводе и размонтировании. Предусмотрите загрузку, ошибку и пустой результат. Это учебный пример: он не должен считаться полностью готовым для production или исчерпывающей реализацией всех особенностей ARIA-компонентов.', 'TypeScript и React', 'import { useEffect, useId, useState } from "react";
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-TH-001', 'Fullstack', 'Junior', 'Теория', 'Теория 001', 'Чем обычно отличаются HTTP-методы GET и POST? Какой метод выбрать для получения списка вакансий и почему?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-TH-002', 'Fullstack', 'Junior', 'Теория', 'Теория 002', 'Почему SQL-запрос с пользовательским вводом следует параметризовать? Покажите пример поиска приглашений кандидата.', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-TH-003', 'Fullstack', 'Junior', 'Теория', 'Теория 003', 'Для чего в React используют состояние компонента? Как отобразить состояние приглашения, загруженное с сервера?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-TH-004', 'Fullstack', 'Junior', 'Теория', 'Теория 004', 'В каких случаях API возвращает 400, 401, 403 и 404? Приведите пример для принятия приглашения.', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-TH-005', 'Fullstack', 'Junior', 'Теория', 'Теория 005', 'Зачем валидировать диапазон зарплаты при создании приглашения и на клиенте, и на сервере?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-AN-001', 'Fullstack', 'Junior', 'Анализ', 'Анализ 001', 'В форме поиска меняется специализация. Найдите проблему в коде и объясните, что увидит пользователь: const [specialization, setSpecialization] = useState(''''); const [jobs, setJobs] = useState([]); useEffect(() => { fetch(''/api/jobs?specialization='' + specialization).then(r => r.json()).then(setJobs); }, []); Почему список не обновляется после выбора фильтра? Назовите еще одну важную обработку для такого запроса.', 'TypeScript, React', NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-AN-002', 'Fullstack', 'Junior', 'Анализ', 'Анализ 002', 'Обработчик поиска работодателя: app.get(''/api/jobs'', async (req, res) => { const sql = "SELECT id, title FROM jobs WHERE specialization = ''" + req.query.specialization + "''"; const rows = await db.all(sql); res.json(rows); }); Какие две конкретные проблемы есть в примере? Предложите безопасный способ выполнения запроса и укажите еще одну нужную проверку API.', 'TypeScript, Node.js, Express, SQL', NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('J-FS-PR-001', 'Fullstack', 'Junior', 'Практика', 'Практика 001', 'Реализуйте функцию проверки диапазона зарплаты приглашения. Диапазон задается в целых рублях: минимум и максимум должны быть конечными целыми числами, минимум не меньше нуля, максимум не меньше минимума и не больше 10 000 000. Функция должна вернуть валидный нормализованный объект либо список понятных ошибок. Не изменяйте входной объект. Проверить нужно также отсутствующие и нечисловые значения.', 'TypeScript, Node.js; интерфейс функции без фреймворка', 'type SalaryRange = { min: number; max: number }; type ValidationResult = { ok: true; value: SalaryRange } | { ok: false; errors: string[] }; export function validateSalaryRange(input: unknown): ValidationResult { // Реализуйте проверку и возврат результата. return { ok: false, errors: [''not_implemented''] }; } // Примеры входа: { min: 80000, max: 120000 }, { min: -1, max: 120000 }, { min: 150000, max: 120000 }, { min: ''80000'', max: 120000 }.', '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-TH-001', 'Fullstack', 'Middle', 'Теория', 'Теория 001', 'Чем проверка аутентификации отличается от авторизации? Как это различие применить к приватному профилю кандидата и приглашению работодателя?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-TH-002', 'Fullstack', 'Middle', 'Теория', 'Теория 002', 'Как предотвратить двойное принятие приглашения при двух почти одновременных запросах? Назовите роль транзакции и условного обновления.', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-TH-003', 'Fullstack', 'Middle', 'Теория', 'Теория 003', 'Что такое проблема N+1 при выдаче подборки профилей и как ее обнаружить и уменьшить?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-TH-004', 'Fullstack', 'Middle', 'Теория', 'Теория 004', 'Как проектировать статусы приглашения и обрабатывать повторный запрос клиента?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-TH-005', 'Fullstack', 'Middle', 'Теория', 'Теория 005', 'Как сделать обработчик Express удобным для тестирования и корректно преобразовать ошибки предметной области в HTTP-ответы?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-AN-001', 'Fullstack', 'Middle', 'Анализ', 'Анализ 001', 'Рассмотрите обработчик: app.post(''/api/invitations/:id/accept'', async (req, res) => { const invitation = await db.get(''SELECT * FROM invitations WHERE id = ?'', [req.params.id]); if (!invitation || invitation.status !== ''pending'') return res.sendStatus(409); if (invitation.candidate_id !== req.user.id) return res.sendStatus(403); await db.run("UPDATE invitations SET status = ''accepted'' WHERE id = ?", [req.params.id]); res.sendStatus(204); }); Определите гонку и проблему порядка/границ доступа. Предложите безопасную логику, включая интерпретацию результата.', 'TypeScript, Node.js, Express, SQL', NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-AN-002', 'Fullstack', 'Middle', 'Анализ', 'Анализ 002', 'Компонент при выборе другой вакансии запрашивает подробности кандидата: function Candidate({jobId}:{jobId:string}) { const [profile,setProfile] = useState<any>(null); useEffect(() => { fetch(''/api/jobs/''+jobId+''/candidate'').then(r=>r.json()).then(setProfile); }, [jobId]); return <div>{profile?.name}</div>; } Какие существенные сценарии не обработаны? Предложите исправление, учитывающее ответ сервера, отмену запроса и приватность контактов.', 'TypeScript, React', NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('M-FS-PR-001', 'Fullstack', 'Middle', 'Практика', 'Практика 001', 'Реализуйте endpoint принятия приглашения. Используйте переданный middleware аутентификации: req.user.id — ID кандидата. Допущение: SQLite-драйвер предоставляет db.run(sql, params), возвращающий объект с changes; база доступна как db. Разрешено принимать только приглашение этого кандидата со статусом pending. Успех — 204, приглашение отсутствует либо переход невозможен — 404 или 409 с согласованной семантикой (выберите и последовательно примените); ошибки БД передайте next. Не раскрывайте контакты. Представьте весь маршрут и необходимые типы.', 'TypeScript, Node.js, Express, SQL (SQLite)', 'import { Router, Request, Response, NextFunction } from ''express''; type AuthRequest = Request & { user: { id: number } }; type RunResult = { changes: number }; type Database = { run(sql: string, params: unknown[]): Promise<RunResult> }; export function invitationRouter(db: Database): Router { const router = Router(); router.post(''/:id/accept'', async (req: AuthRequest, res: Response, next: NextFunction) => { // Middleware выше маршрута устанавливает req.user. // Реализуйте проверку ID и атомарный переход. return res.status(501).json({ error: ''not_implemented'' }); }); return router; }', '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-TH-001', 'Fullstack', 'Senior', 'Теория', 'Теория 001', 'Как спроектировать сквозной поток приглашения: от создания работодателем до согласия кандидата и раскрытия контактов? Назовите границы доверия и инварианты.', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-TH-002', 'Fullstack', 'Senior', 'Теория', 'Теория 002', 'Как обеспечить согласованность между записью приглашения и отправкой уведомления, если база данных и почтовый сервис не участвуют в общей транзакции?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-TH-003', 'Fullstack', 'Senior', 'Теория', 'Теория 003', 'Какие решения нужны для безопасного поиска и подбора кандидатов при росте объема данных? Обсудите пагинацию, индексы и защиту приватности.', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-TH-004', 'Fullstack', 'Senior', 'Теория', 'Теория 004', 'Как спроектировать аудит статусов приглашений и одновременно не превратить журнал в источник утечки персональных данных?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-TH-005', 'Fullstack', 'Senior', 'Теория', 'Теория 005', 'Как организовать надежную обработку ошибок и деградацию интерфейса при недоступности части сервиса подбора?', NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-AN-001', 'Fullstack', 'Senior', 'Анализ', 'Анализ 001', 'Проект хранит приглашения в PostgreSQL. Код выполняет SELECT приглашения и согласия, затем отдает профиль с контактами, если consent=true. Обе записи могут измениться между SELECT и ответом; кэш профиля общий для всех работодателей, ключ cache:profile:<profileId>. Предложите сквозное исправление: граница транзакции, проверка доступа, кэширование, отзыв согласия и проверяемые инварианты. Не предполагайте, что кэширование разрешено требованиями продукта.', 'TypeScript, Node.js, Express, SQL (PostgreSQL)', NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-AN-002', 'Fullstack', 'Senior', 'Анализ', 'Анализ 002', 'В компоненте подбора ответ сервера содержит публичные поля и иногда contacts. Код: const [results,setResults]=useState([]); useEffect(()=>{ fetch(''/api/matches'').then(r=>r.json()).then(setResults); },[]); return results.map((x:any)=><Candidate key={x.id} data={x}/>); Candidate скрывает телефон стилем CSS до клика «согласен». Проанализируйте клиентские и системные дефекты. Предложите архитектурное исправление при условии, что согласие фиксируется сервером.', 'TypeScript, React', NULL, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
INSERT INTO hackathon_tasks_public (id, specialization, grade, type, title, prompt, language, starter_code, options, example) VALUES ('S-FS-PR-001', 'Fullstack', 'Senior', 'Практика', 'Практика 001', 'Спроектируйте и реализуйте сервисное ядро создания приглашения. Вход включает работодателя, кандидата, специализацию и зарплатный диапазон в рублях. Допущения: вызывающая сторона уже аутентифицирована; предоставлены интерфейсы транзакции и репозитория; профили и категории существуют. Приглашение создается только работодателем, диапазон — целые рубли от 0 до 10 000 000 включительно, min ≤ max; запрещено создавать повторное активное приглашение для пары работодатель-кандидат-специализация. Покажите стартовый код с интерфейсами и незавершенной функцией, затем реализуйте атомарную операцию с понятными предметными ошибками. Уведомления здесь не отправляйте; укажите, где было бы место для надежного outbox-потока.', 'TypeScript, Node.js, Express, SQL (PostgreSQL)', 'type InvitationInput={employerId:number;candidateId:number;specialization:string;salaryMin:number;salaryMax:number}; type Invitation={id:number;employerId:number;candidateId:number;specialization:string;salaryMin:number;salaryMax:number;status:''pending''}; type Tx={findActive(employerId:number,candidateId:number,specialization:string):Promise<Invitation|null>; insert(input:InvitationInput):Promise<Invitation>; addOutbox?(event:unknown):Promise<void>}; type Repository={transaction<T>(work:(tx:Tx)=>Promise<T>):Promise<T>}; export async function createInvitation(repo:Repository,input:InvitationInput):Promise<Invitation>{ // Проверьте поля и атомарно создайте приглашение. throw new Error(''not_implemented''); }', '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET specialization=EXCLUDED.specialization, grade=EXCLUDED.grade, type=EXCLUDED.type, title=EXCLUDED.title, prompt=EXCLUDED.prompt, language=EXCLUDED.language, starter_code=EXCLUDED.starter_code, options=EXCLUDED.options, example=EXCLUDED.example;
